  ('ed23285d-d250-56cb-9552-a170bc34b8d2', '2cc007cb-f0b0-540b-afa1-987cd7fb0698', 'missa', 0, null::smallint[], '19:30', '')
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('4eea1b86-c7d2-5b79-885d-21bd7910e23e', 'A arquidiocese não publica foranias nem setores; região Central (programação de Corpus Christi 2026). Outro telefone publicado: (65) 99983-2729. Fora do formato: Adoração ao Santíssimo todas as quintas-feiras, sem horário publicado.', '{"https://arquidiocesecuiaba.org.br/paroquia/catedral-basilica-senhor-bom-jesus-de-cuiaba/","https://arquidiocesecuiaba.org.br/horarios-de-missas/"}', 'alta'),
  ('78254394-94d3-5b9f-923b-fe9d83c6069b', 'A arquidiocese não publica foranias nem setores; região Morada da Serra (Corpus Christi 2026). As 7 comunidades são as da página da arquidiocese; o bairro de cada uma vem do site da paróquia.', '{"https://arquidiocesecuiaba.org.br/paroquia/coracao-imaculado-de-maria/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://coracaoimaculado.no.comunidades.net/calendario","https://coracaoimaculado.no.comunidades.net/contatos"}', 'alta'),
  ('a8a5c099-f86c-55a9-a20c-da02b030542f', 'A arquidiocese não publica foranias nem setores; Várzea Grande. Outro telefone publicado: (65) 9991-0784. Fora do formato: Outras comunidades sem bairro na fonte: São João Batista e Nossa Senhora do Migrante.', '{"https://arquidiocesecuiaba.org.br/paroquia/cristo-rei/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/"}', 'alta'),
  ('98e74fbf-6aad-51e3-aab9-45019e141ac6', 'A arquidiocese não publica foranias nem setores; região CPA (Corpus Christi 2026). Padres scalabrinianos. O GCatholic a lista também como santuário. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/divino-espirito-santo/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/"}', 'alta'),
  ('1ddd7d98-2dbc-5236-9031-ba57a5f52227', 'A arquidiocese não publica foranias nem setores; região Coxipó (Corpus Christi 2026). Frades capuchinhos. Criada em 1988. Fora do formato: Missa todo dia 12 do mês às 5h.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-aparecida-cuiaba/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/comunidades-da-arquidiocese-de-cuiaba-celebram-nossa-senhora-aparecida-com-missas-e-procissoes/"}', 'alta'),
  ('3515542b-7164-5036-a8ea-4be11605b847', 'A arquidiocese não publica foranias nem setores; Região Metropolitana. Criada em 2007, desmembrada de Acorizal. Na sexta, a página diz 19h e ''1ª sexta às 19h'': lido como só a primeira sexta. Fora do formato: Capela Nossa Senhora das Graças, sem lugar na fonte. A paróquia diz ter 21 comunidades rurais. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-aparecida-jangada/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/"}', 'alta'),
  ('d3ace5af-8949-5476-9373-50be83799f72', 'A arquidiocese não publica foranias nem setores; região Coxipó (Corpus Christi 2026). Paróquia de 1947, a do Coxipó da Ponte. O GCatholic a lista também como santuário. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-da-guia-cuiaba/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/saiba-onde-participar-de-missa-diaria-durante-o-retiro-do-clero/"}', 'alta'),
  ('f8fe25ce-0c08-57bb-a712-99678b7c18d2', 'A arquidiocese não publica foranias nem setores; Distrito da Guia (distrito de Cuiabá). A página não traz telefone, e-mail nem endereço; a missa de semana diverge entre a página (19h) e a notícia do retiro (18h30). Fora do formato: Na semana do retiro do clero de 2026 a arquidiocese publicou a matriz de terça a sexta às 18h30 e a Igreja Imaculado Coração de Maria (Florais) de segunda a sexta às 6h. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-da-guia-distrito-da-guia/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/saiba-onde-participar-de-missa-diaria-durante-o-retiro-do-clero/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/"}', 'media'),
  ('89f324f9-3684-5a6f-8799-9ed85c1b4bb0', 'A arquidiocese não publica foranias nem setores; Várzea Grande. Missionários Saletinos. A página da paróquia diz que as missas são na Igreja Matriz Nossa Senhora do Carmo; a Igrejinha da Guia, no centro, é patrimônio. Fora do formato: Outras comunidades sem bairro na fonte: Divino Espírito Santo, Menino Jesus e Nossa Senhora das Graças.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-da-guia-varzea-grande/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/saiba-onde-participar-de-missa-diaria-durante-o-retiro-do-clero/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/","https://arquidiocesecuiaba.org.br/34a-romaria-de-nossa-senhora-da-salette-celebra-180-anos-de-reconciliacao-e-fe-em-cuiaba/"}', 'alta'),
  ('ea44ad0b-beeb-5cbd-bf5a-80a5051cd3f4', 'A arquidiocese não publica foranias nem setores; Região Metropolitana. Sem horário: a página da paróquia no site da arquidiocese está vazia (sem horários, telefone, e-mail ou endereço) e a busca não achou fonte oficial. Criada em 1974. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-das-dores/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/","https://arquidiocesecuiaba.org.br/padre-enivaldo-e-empossado-paroco-em-barao-de-melgaco/"}', ''),
  ('34528b18-6091-5c49-93f0-433cd11c6600', 'A arquidiocese não publica foranias nem setores; Várzea Grande. Criada em 2005. O outro telefone publicado (65 999264-5956) tem um dígito a mais e ficou fora. Fora do formato: Comunidades sem bairro na fonte: São José Operário, Santa Luzia, Santa Clara, Santo Antônio e São Francisco. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-das-gracas/","https://arquidiocesecuiaba.org.br/horarios-de-missas/"}', 'alta'),
  ('23f18aaf-9942-5c28-b316-15da699b2d00', 'A arquidiocese não publica foranias nem setores; Região Metropolitana. A página não traz o endereço da matriz, só o CEP 78485-000. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-de-brotas/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/","https://arquidiocesecuiaba.org.br/comunidades-da-arquidiocese-de-cuiaba-celebram-nossa-senhora-aparecida-com-missas-e-procissoes/"}', 'alta'),
  ('2abe905f-2289-5902-87e8-6498428547cc', 'A arquidiocese não publica foranias nem setores; Cuiabá. Frades franciscanos (OFM). Sem telefone, e-mail e endereço na página; bairro Quilombo e ''próxima ao Parque Mãe Bonifácia'' vêm de notícias da arquidiocese. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-de-guadalupe/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/","https://arquidiocesecuiaba.org.br/nossa-senhora-de-guadalupe-na-arquidiocese-de-cuiaba/","https://arquidiocesecuiaba.org.br/jubileu-de-ouro-ovisa-celebra-50-anos-na-arquidiocese-de-cuiaba/"}', 'alta'),
  ('09272ae8-5500-57b4-a269-65cb952f6887', 'A arquidiocese não publica foranias nem setores; Várzea Grande, bairro Chapéu do Sol. Frades Menores Missionários. Sem contatos na página. O nome da matriz (Nossa Senhora de Guadalupe) vem só da notícia da festa de Aparecida de 2026. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-do-pantanal/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/comunidades-da-arquidiocese-de-cuiaba-celebram-nossa-senhora-aparecida-com-missas-e-procissoes/","https://arquidiocesecuiaba.org.br/saiba-onde-participar-de-missa-diaria-durante-o-retiro-do-clero/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/","https://arquidiocesecuiaba.org.br/dom-mario-celebra-missa-de-envio-com-a-equipe-de-coordenacao-da-cebs/"}', 'media'),
  ('a291c56e-367e-5605-995c-60b317e7526e', 'A arquidiocese não publica foranias nem setores; Região Metropolitana. Paróquia de 1833. Comunidades urbanas e rurais conforme a página da paróquia no site da arquidiocese. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-do-rosario-rosario-oeste/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/","https://arquidiocesecuiaba.org.br/comunidades-da-arquidiocese-de-cuiaba-celebram-nossa-senhora-aparecida-com-missas-e-procissoes/"}', 'alta'),
  ('d21a7f08-6345-5b8e-8673-759ec30e78f3', 'A arquidiocese não publica foranias nem setores; Cuiabá, centro histórico. Padres jesuítas. Igreja de 1730. Em 2025 cedeu 12 comunidades à Área Pastoral Santíssima Trindade. Outro telefone publicado: (65) 99981-8095. Fora do formato: Outras comunidades sem bairro na fonte: São Pedro e Cristo Redentor. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-do-rosario-e-sao-benedito/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/saiba-onde-participar-de-missa-diaria-durante-o-retiro-do-clero/","https://arquidiocesecuiaba.org.br/comunidades-da-arquidiocese-de-cuiaba-celebram-nossa-senhora-aparecida-com-missas-e-procissoes/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/"}', 'alta'),
  ('1e5e9dcb-116d-59b3-9c17-82b05665e815', 'A arquidiocese não publica foranias nem setores; Cuiabá. Fundada em 1960 pelos franciscanos. Outro telefone publicado: (65) 9 9997-2529. Fora do formato: Comunidade Nossa Senhora do Carmo, sem lugar na fonte.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-mae-dos-homens/","https://arquidiocesecuiaba.org.br/horarios-de-missas/"}', 'alta'),
  ('f1ff0d4a-4d67-5706-80cb-c4a3114fcec5', 'A arquidiocese não publica foranias nem setores; Cuiabá. Criada em 14/11/1979. Fora do formato: Comunidades sem bairro na fonte: São José, São João Batista, São Benedito, Nossa Senhora do Perpétuo Socorro, Santa Izabel, São Francisco, São Benedito do Pari (ao lado do cemitério) e Nossa Senhora de Fátima.', '{"https://arquidiocesecuiaba.org.br/paroquia/nossa-senhora-medianeira-de-todas-as-gracas/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/saiba-onde-participar-de-missa-diaria-durante-o-retiro-do-clero/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/"}', 'alta'),
  ('8d65371a-aa4a-5dd3-8d68-754191d2bf97', 'A arquidiocese não publica foranias nem setores; Região Metropolitana. Sem horário: a página da paróquia no site da arquidiocese não traz horários nem contatos, e a busca não achou fonte oficial. O nome da igreja matriz não é publicado. Fora do formato: A arquidiocese cita 3 comunidades dedicadas a Nossa Senhora Aparecida, sem nomear os lugares.', '{"https://arquidiocesecuiaba.org.br/paroquia/rural-de-santa-cruz-das-palmeiras/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/","https://arquidiocesecuiaba.org.br/dom-mario-celebra-25-anos-da-comunidade-fraterna-no-amor/"}', ''),
  ('e107d260-66da-50c7-8149-a8694c2f9e46', 'A arquidiocese não publica foranias nem setores; Cuiabá. Criada em 1999. A notícia do retiro de 2026 dá a missa de quinta à noite às 19h30; a página da paróquia diz 19h. Fora do formato: Confissões também terça e sábado após a missa das 6h. Comunidades sem bairro na fonte: Imaculada Conceição, São Francisco Xavier e Santo Antônio.', '{"https://arquidiocesecuiaba.org.br/paroquia/sagrada-familia/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/","https://arquidiocesecuiaba.org.br/nossa-senhora-de-guadalupe-na-arquidiocese-de-cuiaba/"}', 'alta'),
  ('f35b9c71-f946-5992-8881-dcc849ad65e1', 'A arquidiocese não publica foranias nem setores; Várzea Grande. Padres estigmatinos (CSS). Fora do formato: Comunidades sem bairro na fonte: N. S. Aparecida (domingo 6h30 e 18h; sexta 19h30), Santo Antônio (domingo 8h; 1ª sexta 19h30), Sagrado Coração de Jesus (1º e 3º domingos 8h), São Paulo Apóstolo (domingo 9h30), São Benedito (domingo 9h30), São José (1º sábado 16h), Santa Luzia (3º sábado 19h30), Jesus, Maria e José (4º sábado 16h).', '{"https://arquidiocesecuiaba.org.br/paroquia/santa-edwiges/","https://arquidiocesecuiaba.org.br/horarios-de-missas/"}', 'alta'),
  ('f63e3ca6-c6f6-56fa-8661-9a8039893198', 'A arquidiocese não publica foranias nem setores; Região Metropolitana. Paróquia de 1835.', '{"https://arquidiocesecuiaba.org.br/paroquia/santo-antonio-santo-antonio-de-leverger/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/"}', 'alta'),
  ('16e18889-35e2-5ae2-b1de-5cd01c15bd0f', 'A arquidiocese não publica foranias nem setores; Várzea Grande. Criada em 24/10/2009. Fora do formato: Missa todo dia 13 às 19h30. Comunidades sem bairro na fonte: São João Bosco, Sagrado Coração de Jesus, Rainha da Paz, Imaculada Conceição e Senhor Bom Jesus. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/santo-antonio-de-padua-varzea-grande/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/","https://arquidiocesecuiaba.org.br/confira-a-programacao-de-corpus-christi-na-arquidiocese-de-cuiaba/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/"}', 'alta'),
  ('2521b031-ad4a-58f5-b8a6-6fdbdbe0cb57', 'A arquidiocese não publica foranias nem setores; Cuiabá, Morro do Seminário. Paróquia e santuário (tem pároco e secretaria paroquial); o GCatholic o lista só como santuário. Fora do formato: Confissões de segunda a sexta após as missas das 7h e das 18h. Adoração eucarística semanal, sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/santuario-eucaristico-nossa-senhora-do-bom-despacho/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/saiba-onde-participar-de-missa-diaria-durante-o-retiro-do-clero/"}', 'alta'),
  ('30ac3063-4e78-5e46-b768-8eef09e8f4bb', 'A arquidiocese não publica foranias nem setores; região Morada do Ouro (Corpus Christi 2026). Memorial da visita de 1991, santuário desde 2011; paróquia com pároco e secretaria paroquial.', '{"https://arquidiocesecuiaba.org.br/paroquia/santuario-eucaristico-sao-joao-paulo-ii/","https://arquidiocesecuiaba.org.br/horarios-de-missas/"}', 'alta'),
  ('07306f7e-867a-5d17-a018-1166d37453d6', 'A arquidiocese não publica foranias nem setores; região Pascoal Ramos (Corpus Christi 2026). Padres dehonianos (SCJ). A página só traz as missas de domingo. Fora do formato: A página publica sem dizer o tipo: quarta 15h às 18h na Comunidade São Pedro; terça, quinta e sexta 9h às 12h e 15h às 18h, e sábado 9h às 12h, na matriz. Na semana do retiro de 2026 houve missa na matriz quinta 19h30 e na Comunidade São Pedro quarta 19h30.', '{"https://arquidiocesecuiaba.org.br/paroquia/santuario-nossa-senhora-da-medalha-milagrosa/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/saiba-onde-participar-de-missa-diaria-durante-o-retiro-do-clero/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/","https://arquidiocesecuiaba.org.br/comunidades-da-arquidiocese-de-cuiaba-celebram-nossa-senhora-aparecida-com-missas-e-procissoes/"}', 'media'),
  ('bebac14a-58bb-5399-aa12-27c2e8f3fee0', 'A arquidiocese não publica foranias nem setores; Cuiabá. Padres salesianos. Paróquia de 1781. Fora do formato: Comunidade São Domingos Sávio, sem lugar na fonte.', '{"https://arquidiocesecuiaba.org.br/paroquia/sao-goncalo/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/saiba-onde-participar-de-missa-diaria-durante-o-retiro-do-clero/","https://arquidiocesecuiaba.org.br/comunidades-da-arquidiocese-de-cuiaba-celebram-nossa-senhora-aparecida-com-missas-e-procissoes/"}', 'alta'),
  ('e69d98cc-dd34-5484-987a-1fc2e37b15e0', 'A arquidiocese não publica foranias nem setores; Cuiabá. Criada em 1971. Outro telefone publicado: (65) 99981-1835. A página não dá o bairro.', '{"https://arquidiocesecuiaba.org.br/paroquia/sao-joao-bosco/","https://arquidiocesecuiaba.org.br/horarios-de-missas/"}', 'alta'),
  ('fdb25183-4e8c-51cd-bb80-b123d0e8df48', 'A arquidiocese não publica foranias nem setores; região Imperial (festa de Aparecida 2026). Criada em 2024. Fora do formato: Missa votiva a São Mateus todo dia 21 às 19h30. Comunidades sem bairro na fonte: Bom Pastor, Santa Cruz, São Miguel e Santa Marta.', '{"https://arquidiocesecuiaba.org.br/paroquia/sao-mateus/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/"}', 'alta'),
  ('4bce8947-84e1-50ef-9e81-0f9ab9ee94e6', 'A arquidiocese não publica foranias nem setores; Cuiabá, bairro Três Barras. Criada em 2024, desmembrada da Coração Imaculado de Maria. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesecuiaba.org.br/paroquia/sao-sebastiao-3-barras-cuiaba/","https://arquidiocesecuiaba.org.br/horarios-de-missas/"}', 'alta'),
  ('36b918fe-0d85-5d17-9e57-0a0bbba20549', 'A arquidiocese não publica foranias nem setores; Região Metropolitana. Criada em 1975.', '{"https://arquidiocesecuiaba.org.br/paroquia/sao-sebastiao-nobres/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/","https://arquidiocesecuiaba.org.br/missas-de-finados-serao-realizadas-em-todas-as-paroquias-e-cemiterios-da-arquidiocese-de-cuiaba/"}', 'alta'),
  ('94ddf8de-7920-506c-86ad-19648165f811', 'A arquidiocese não publica foranias nem setores; Várzea Grande. Criada em 1984. O e-mail publicado (paseba@cuiabaarquidiosece.net) tem o domínio grafado errado e ficou fora.', '{"https://arquidiocesecuiaba.org.br/paroquia/sao-sebastiao-varzea-grande/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/"}', 'alta'),
  ('31bfd17b-22fc-56dd-8ce0-eaa73433f7b6', 'A arquidiocese não publica foranias nem setores; Cuiabá. Criada em 1968. Telefone da secretaria também publicado: (65) 99226-0973. Fora do formato: Comunidades sem bairro na fonte: São Paulo Apóstolo (terça e sábado 19h), São Mateus (sexta 19h; domingo 8h30), São João Batista (sexta 19h; domingo 8h30 e 18h), Santa Teresinha (quarta e sábado 19h).', '{"https://arquidiocesecuiaba.org.br/paroquia/universitaria-sao-jose-operario/","https://arquidiocesecuiaba.org.br/horarios-de-missas/","https://arquidiocesecuiaba.org.br/33-comunidades-da-arquidiocese-de-cuiaba-tem-nossa-senhora-aparecida-como-padroeira/","https://arquidiocesecuiaba.org.br/saiba-onde-participar-de-missa-diaria-durante-o-retiro-do-clero/"}', 'alta'),
  ('e366c30d-b8a8-59a0-9323-7ac726eed502', 'A arquidiocese não publica foranias nem setores; Cuiabá, saída para Chapada dos Guimarães. Criada em 1º/08/2025 com 12 comunidades da Paróquia N. S. do Rosário e São Benedito, rumo a nova paróquia. Sem matriz definida (a primeira igreja é a comunidade onde ocorrem os eventos) e sem horário publicado.', '{"https://arquidiocesecuiaba.org.br/arquidiocese-inicia-atividades-para-criacao-de-nova-paroquia-na-saida-para-chapada/","https://arquidiocesecuiaba.org.br/santa-missa-marca-inicio-da-area-pastoral-santissima-trindade-em-cuiaba/","https://arquidiocesecuiaba.org.br/bazar-da-area-pastoral-ajudara-na-criacao-da-nova-paroquia/"}', ''),
  ('1347d5df-af3d-505a-bb6e-f15666c1b4dc', 'Forania de Sinop. Horário do perfil da catedral no Instagram, lido só pelo trecho da busca (publicação de cerca de dois anos). Contatos do site da diocese (2020).', '{"https://diocesedesinop.com.br/foranias/forania-de-sinop/paroquia-sagrado-coracao-de-jesus/","https://www.instagram.com/catedralsinop/"}', 'media'),
  ('440bef58-d640-557b-a65c-5729a7c1b363', 'Forania de Sinop. Horário do perfil da paróquia no Instagram, lido só pelo trecho da busca, sem data.', '{"https://diocesedesinop.com.br/foranias/forania-de-sinop/paroquia-sao-francisco-de-assis/","https://www.instagram.com/paroquiasfasinop/"}', 'media'),
  ('41b1a476-1576-5f2e-932d-344874fab634', 'Forania de Sinop. Sem horário publicado pela paróquia ou pela diocese (site da diocese parado desde 2022). Endereço do perfil da paróquia no Instagram; o site da diocese (2020) dava Rua das Tumbérgias, 227.', '{"https://diocesedesinop.com.br/foranias/forania-de-sinop/paroquia-sao-camilo/","https://www.instagram.com/p.saocamilosinop/"}', ''),
  ('f039cab1-af3d-516d-a478-472fe7a6488d', 'Forania de Sinop. Sem horário publicado pela paróquia ou pela diocese (site da diocese parado desde 2022).', '{"https://diocesedesinop.com.br/foranias/forania-de-sinop/paroquia-sao-cristovao/","https://www.instagram.com/saocristovaosinop/"}', ''),
  ('11eb7cf2-34ed-5413-b5e3-7128d7b1e6ba', 'Forania de Sinop. Sem horário publicado pela paróquia ou pela diocese (site da diocese parado desde 2022). Telefone e WhatsApp da secretaria do perfil da paróquia no Instagram; o site da diocese (2020) dava 3531-2692.', '{"https://diocesedesinop.com.br/foranias/forania-de-sinop/paroquia-santo-antonio/","https://www.instagram.com/paroquiasantoantoniosinop/"}', ''),
  ('21b830de-4088-50f5-a987-72c32ba4517c', 'Forania de Sinop. Sem horário publicado pela paróquia ou pela diocese (site da diocese parado desde 2022).', '{"https://diocesedesinop.com.br/foranias/forania-de-sinop/paroquia-nossa-senhora-da-gloria/","https://www.instagram.com/p.n.senhoradagloria/"}', ''),
  ('0ccca782-a3d4-59d4-bf2d-28c6ffeda76b', 'Forania de Vera. Horários do site da paróquia (página de horários e páginas das comunidades), lido em 13/11/2026. O site da diocese (2020) dava a sede na Av. Natalino Brescansin, 1592. Fora do formato: As missas da matriz são celebradas no GESP, segundo a paróquia. Comunidades sem bairro na fonte: Imaculado Coração de Maria (celebração na 3ª terça do mês, às 19h), Nossa Senhora do Rosário e São Cristóvão.; A página de horários diz quinta, 19h30; a da comunidade, missa na 3ª quinta e celebração da Palavra na 1ª e na última.; A página da comunidade diz missa na 4ª terça do mês, às 19h30, e celebração da Palavra aos sábados, às 19h30.; Adoração também na última quinta-feira do mês.; Missa todo dia 13, às 19h30. Santuário em construção.; A página de horários diz toda quarta; a da comunidade, 2ª quarta-feira do mês.; Nos outros sábados, celebração da Palavra às 19h.; Nas outras sextas, celebração da Palavra às 19h30.; A página da comunidade diz missa no 2º e no 4º domingo, às 8h30.; Missa na última sexta-feira do mês, às 19h30.; A página da comunidade fala do Jardim Primavera. Ponto no mapa aproximado: centro da cidade.', '{"https://www.pspedrosorriso.com.br/institucional/horarios-de-missa","https://www.pspedrosorriso.com.br/secretaria","https://www.pspedrosorriso.com.br/comunidade/igreja-sao-pedro-apostolo--matriz/","https://diocesedesinop.com.br/foranias/forania-de-vera/paroquia-sao-pedro-apostolo-sorriso/"}', 'alta'),
  ('ddd89053-9229-5e4b-bc9c-afba188f7cf6', 'Forania de Vera. Sem horário publicado pela paróquia ou pela diocese (site da diocese parado desde 2022).', '{"https://diocesedesinop.com.br/foranias/forania-de-vera/paroquia-santa-luzia/"}', ''),
  ('19dfabf8-5dc3-5988-a841-3b965a5d64de', 'Forania de Vera. Sem horário publicado pela paróquia ou pela diocese (site da diocese parado desde 2022).', '{"https://diocesedesinop.com.br/foranias/forania-de-vera/paroquia-sao-judas-tadeu/"}', ''),
